/*
 * A (distinct) instance of this structure
 * is passed to each thread
 */
struct thread_info_struct {
        pthread_t tid; /* POSIX thread id, as returned by the library */

        int *color_val; /* Pointer to array to manipulate */
        int thrid; /* Application-defined thread id */
        int thrcnt;
};

int safe_atoi(char *s, int *val)
{
        long l;
        char *endp;

        errno = 0;
        l = strtol(s, &endp, 10);
        if (errno != ERANGE && l >= INT_MIN && l <= INT_MAX &&
            s != endp && *endp == '\0') {
                *val = l;
                return 0;
        } else
                return -1;
}

void usage(char *argv0)
{
        fprintf(stderr, "Usage: %s thread_count\n\n"
                "Exactly one argument required:\n"
                "    thread_count: The number of threads to create.\n",
                argv0);
        exit(1);
}

void *safe_malloc(size_t size)
{
        void *p;

        if ((p = malloc(size)) == NULL) {
                fprintf(stderr, "Out of memory, failed to allocate %zd bytes\n",
                        size);
                exit(1);
        }

        return p;
}

/* Start function for each thread */
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t *cond;
int counter = 0;

thrcnt, ret;
	struct thread_info_struct *thr;

	// Signal Handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
	sa.sa_handler = sig_handler;
    if (sigaction(SIGINT, &sa, NULL) < 0)
    {
        perror("sigaction");
        exit(1);
    }

	/*
         * Parse the command

if (safe_atoi(argv[1], &thrcnt) < 0 || thrcnt <= 0) {
    fprintf(stderr, "`%s' is not valid for `thread_count'\n", argv[1]);
    exit(1);
}


	thr = safe_malloc(thrcnt * sizeof(*thr));
	cond = safe_malloc(thrcnt * sizeof(pthread_cond_t));

	/* Initialize every condition before any worker can signal its successor. */
	for (int i = 0; i < thrcnt; i++) {
		ret = pthread_cond_init(&cond[i], NULL);
		if (ret) {
			perror_pthread(ret, "pthread_cond_init");
			exit(1);
		}
	}

	for(int i=0; i<thrcnt; i++)
	{
		thr[i].thrcnt = thrcnt;
		thr[i].thrid = i;
		thr[i].color_val = safe_malloc(x_chars * sizeof(int));

		/* Spawn new thread */
        ret = pthread_create(&thr[i].tid, NULL, compute_and_output_mandel_line, &thr[i]);
        if (ret) {
            perror_pthread(ret, "pthread_create");
            exit(1);
        }
	}
